public List<List<Integer>> permute(int[] nums) {   
   List<List<Integer>> result = new ArrayList<>();   
   if (nums == null || nums.length == 0) {  
      return result;  
   }   
   int n = nums.length;   
   boolean[] used = new boolean[n];  
   List<Integer> path = new ArrayList<>();  
   // Initialize the first element of the permutation   
   path.add(nums[0]);   
   used[0] = true;   
   // The recursion will be conducted here   
   permuteImpl(nums, n, 1, used, path, result);   
   return result;  
}   

// Recursion method to generate all possible permutations   
private void permuteImpl(int[] nums, int n, int level, boolean[] used, List<Integer> path, List<List<Integer>> result) {   
   // Base case: If the depth reaches the end of the array   
   // Then the permutation of this path is completed  
   if (level == n) {   
      result.add(new ArrayList<Integer>(path));   
      return;  
   }

   // Recursive case  
   for (int i = 0; i < n; i++) {   
      // Skip the used numbers   
      if (used[i] || (i > 0 && !used[i - 1] && nums[i - 1] == nums[i])) continue;  
      path.add(nums[i]);  
      used[i] = true;  
      // Recursive call with the current path  
      permuteImpl(nums, n, level + 1, used, path, result);   
      // Backtrack  
      used[i] = false;  
      path.remove(level);  
   }   
}
```

