        // Loop through all the possible paths from the current n-tersection
        for (int[] path : paths[current[0]][current[1]]) {
            // If the path is not visited, mark it as visited and add it to the queue
            if (!visited[path[0]][path[1]]) {
                visited[path[0]][path[1]] = true;
                queue.add(path);
            }
        }
    }
    // If the queue is empty and we have not reached the ending n-tersection, return "cannot be travelled"
    return "cannot be travelled";
