    // Loop through all the possible paths from the current n-tersection
    for (int i = 0; i < paths.length; i++) {
      // Get the adjacent n-tersection coordinates
      int nextX = paths[i][0];
      int nextY = paths[i][1];

      // Check if the adjacent n-tersection is not visited and not out of bounds
      if (!visited[nextX] && nextX >= 0 && nextY >= 0 && nextX < n && nextY < n) {
        // Mark the adjacent n-tersection as visited and add it to the queue
        visited[nextX] = true;
        queue.add(nextX);
      }
    }
  }

  // If we have visited all the n-tersections and did not reach the ending n-tersection,
  // Then return the result that the maze cannot be travelled
  return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // Initialize a visited matrix to keep track of which n-tersections have been visited
  boolean[][] visited = new boolean[n][n];
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      visited[i][j] = false;
    }
  }

  // Perform a depth-first search to determine if travel is possible
  if (dfs(start, end, 0, 0, visited, paths)) {
    return "can be travelled";
  } else {
    return "cannot be travelled";
  }
}

private static boolean dfs(int[] current, int[] end, int i, int j, boolean[][] visited, int[][] paths) {
  // If we have reached the ending point, return true
  if (i == end[0] && j == end[1]) {
    return true;
  }

  // If we have reached a visited n-tersection, return false
  if (visited[i][j]) {
    return false;
  }

  // Mark the current n-tersection as visited
  visited[i][j] = true;

  // Try moving in all possible directions
  for (int k = 0; k < 4; k++) {
    int ni = i + paths[i][j];
    int nj = j + paths[i + 1][j];

    if (dfs(current, end, ni, nj, visited, paths)) {
      return true;
    }
  }

  return false;
}

