public int findLongestSubstring(String s) {
    int maxLength = 0;
    int start = 0;
    int end = 0;
    int count = 0;
    int[] charCount = new int[3];
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (charCount[c - 'a'] == 0) {
            count++;
        }
        charCount[c - 'a']++;
        while (count > 2) {
            char d = s.charAt(start);
            charCount[d - 'a']--;
            if (charCount[d - 'a'] == 0) {
                count--;
            }
            start++;
        }
        end = i;
        maxLength = Math.max(maxLength, end - start + 1);
    }
    return maxLength;
}
