public int minCostClimbingStairs(int[] cost) {
    int minCost = Integer.MAX_VALUE;
    int start = 0;
    int end = cost.length - 1;
    while (start <= end) {
        int currentCost = cost[start];
        int nextCost = cost[start + 1];
        if (nextCost < currentCost) {
            minCost = Math.min(minCost, nextCost + cost[start + 2]);
        } else {
            minCost = Math.min(minCost, currentCost + cost[start + 1]);
        }
        start++;
    }
    return minCost;
}

