public class GraphSerializer {

    /**
     * Serializes the given Graph instance to a byte array using Protocol Buffers.
     *
     * @param graph the Graph instance to serialize
     * @return a byte array representing the serialized Graph
     */
    public byte[] serialize(Graph graph) {
        Graph.GraphMessage.Builder builder = Graph.GraphMessage.newBuilder();
        builder.setNode(graph.getNode().toProto());
        return builder.build().toByteArray();
    }

    /**
     * Deserializes the given byte array to a Graph instance using Protocol Buffers.
     *
     * @param data the byte array representing the serialized Graph
     * @return a new Graph instance
     * @throws InvalidProtocolBufferException if the byte array cannot be parsed into a GraphMessage
     */
    public Graph deserialize(byte[] data) throws InvalidProtocolBufferException {
        Graph.GraphMessage graphMessage = Graph.GraphMessage.parseFrom(data);
        Node node = Node.fromProto(graphMessage.getNode());
        return new Graph(node);
    }
}
